// ***************
// Filename: sdio_host_top.sv
// Author: FPGA Cores 4 U
// Description: sdio_host with its AXI4-Lite register interface, the block
//   designs and testbenches instantiate: the register map sdio_host_regs
//   (u_regs, src/include/sdio_host_regs.sv, ID "SDIO", VERSION and DATE at
//   0x00-0x08, the registers from 0x10) and the logic sdio_host (u_core,
//   src/sdio_host.sv), joined by their register ports (cfg_* to the logic,
//   sts_* back). Generated by ip/scripts/regmap_gen.py from
//   sdio_host_regs.json and the ports of sdio_host: regenerate after changing
//   either. Clock - aclk. Reset - synchronous active low aresetn.
// Date: 2026-10-12
module sdio_host_top #(
  parameter int BUF_BYTES = 512
) (
  input  logic        aclk,
  input  logic        aresetn,
  input  logic [7:0]  s_axil_awaddr,
  input  logic        s_axil_awvalid,
  output logic        s_axil_awready,
  input  logic [31:0] s_axil_wdata,
  input  logic [3:0]  s_axil_wstrb,
  input  logic        s_axil_wvalid,
  output logic        s_axil_wready,
  output logic [1:0]  s_axil_bresp,
  output logic        s_axil_bvalid,
  input  logic        s_axil_bready,
  input  logic [7:0]  s_axil_araddr,
  input  logic        s_axil_arvalid,
  output logic        s_axil_arready,
  output logic [31:0] s_axil_rdata,
  output logic [1:0]  s_axil_rresp,
  output logic        s_axil_rvalid,
  input  logic        s_axil_rready,
  input  logic [7:0]  s_axis_tdata,
  input  logic        s_axis_tvalid,
  output logic        s_axis_tready,
  output logic [7:0]  m_axis_tdata,
  output logic        m_axis_tvalid,
  input  logic        m_axis_tready,
  output logic        m_axis_tlast,
  output logic        sd_clk_o,
  output logic        cmd_o,
  output logic        cmd_oe_o,
  input  logic        cmd_i,
  output logic [3:0]  dat_o,
  output logic [3:0]  dat_oe_o,
  input  logic [3:0]  dat_i,
  output logic        irq_o
);
  // register ports between the register map and the logic
  logic [10:0] cfg_cmd;
  logic cfg_cmd_wr;
  logic [31:0] cfg_arg;
  logic [127:0] sts_resp;
  logic [7:0] cfg_status;
  logic cfg_status_wr;
  logic [7:0] sts_status;
  logic [17:0] cfg_ctrl;
  logic [10:0] cfg_blksize;
  logic [31:0] cfg_timeout;
  logic [6:0] cfg_irq_en;

  sdio_host_regs u_regs (
    .aclk,
    .aresetn,
    .s_axil_awaddr,
    .s_axil_awvalid,
    .s_axil_awready,
    .s_axil_wdata,
    .s_axil_wstrb,
    .s_axil_wvalid,
    .s_axil_wready,
    .s_axil_bresp,
    .s_axil_bvalid,
    .s_axil_bready,
    .s_axil_araddr,
    .s_axil_arvalid,
    .s_axil_arready,
    .s_axil_rdata,
    .s_axil_rresp,
    .s_axil_rvalid,
    .s_axil_rready,
    .cmd_o(cfg_cmd),
    .cmd_wr_o(cfg_cmd_wr),
    .arg_o(cfg_arg),
    .arg_wr_o(),
    .resp_i(sts_resp),
    .status_o(cfg_status),
    .status_wr_o(cfg_status_wr),
    .status_i(sts_status),
    .ctrl_o(cfg_ctrl),
    .ctrl_wr_o(),
    .blksize_o(cfg_blksize),
    .blksize_wr_o(),
    .timeout_o(cfg_timeout),
    .timeout_wr_o(),
    .irq_en_o(cfg_irq_en),
    .irq_en_wr_o()
  );
  sdio_host #(
    .BUF_BYTES(BUF_BYTES)
  ) u_core (
    .aclk,
    .aresetn,
    .s_axis_tdata,
    .s_axis_tvalid,
    .s_axis_tready,
    .m_axis_tdata,
    .m_axis_tvalid,
    .m_axis_tready,
    .m_axis_tlast,
    .sd_clk_o,
    .cmd_o,
    .cmd_oe_o,
    .cmd_i,
    .dat_o,
    .dat_oe_o,
    .dat_i,
    .irq_o,
    .cfg_cmd,
    .cfg_cmd_wr,
    .cfg_arg,
    .sts_resp,
    .cfg_status,
    .cfg_status_wr,
    .sts_status,
    .cfg_ctrl,
    .cfg_blksize,
    .cfg_timeout,
    .cfg_irq_en
  );
endmodule
